modules["client/cheats.mjs"] = (() => {
const { PLAYER_TRIBES } = modules["server/player-tribes.mjs"];

function createCheats(document, onCommand) {
  const panel = document.createElement("aside");
  panel.id = "cheat-panel";
  panel.className = "cheat-panel";
  panel.setAttribute("aria-labelledby", "cheat-title");
  panel.hidden = true;
  const title = document.createElement("h2");
  title.id = "cheat-title";
  const toggle = document.createElement("button");
  toggle.id = "cheat-toggle";
  toggle.className = "cheat-toggle";
  toggle.type = "button";
  toggle.textContent = "치트 ▾";
  toggle.title = "치트 접기";
  toggle.setAttribute("aria-expanded", "true");
  toggle.setAttribute("aria-controls", "cheat-actions");
  title.append(toggle);
  const actions = document.createElement("div");
  actions.id = "cheat-actions";
  actions.className = "cheat-actions";
  toggle.addEventListener("click", () => {
    actions.hidden = !actions.hidden;
    toggle.textContent = actions.hidden ? "치트 ▸" : "치트 ▾";
    toggle.title = actions.hidden ? "치트 펼치기" : "치트 접기";
    toggle.setAttribute("aria-expanded", String(!actions.hidden));
  });
  const buttons = [
    ["cheat-evolution-points", "진화 +1만", "보유 한도를 넘어 진화 포인트를 10,000점 지급합니다."],
    ["cheat-resources", "재료 +100", "모든 종류의 재료를 창고에 100개씩 지급합니다."],
    ["cheat-upgrade", "둥지 +1", "진화 포인트를 사용하지 않고 둥지를 한 단계 성장시킵니다."],
    ["cheat-heal", "전체 회복", "내 생존 유닛과 본둥지의 체력을 모두 회복합니다. 전초둥지는 회복하지 않습니다."],
    ["cheat-extinction", "멸망", "내 종족의 모든 유닛을 사망시키고 진화 포인트를 0으로 만들어 멸망시킵니다."]
  ].map(([type, label, help]) => {
    const button = document.createElement("button");
    button.id = type;
    button.className = "secondary-action";
    button.type = "button";
    button.textContent = label;
    button.title = help;
    button.disabled = true;
    button.addEventListener("click", () => onCommand({ type }));
    return button;
  });
  const tribes = document.createElement("fieldset");
  tribes.id = "cheat-tribes";
  const legend = document.createElement("legend");
  legend.textContent = "종족 전환";
  tribes.append(legend);
  const tribeButtons = PLAYER_TRIBES.map(tribe => {
    const button = document.createElement("button");
    button.id = "cheat-tribe-" + tribe.key;
    button.className = "secondary-action";
    button.type = "button";
    button.textContent = tribe.name;
    button.title = tribe.name + " 군락의 진행 상태를 유지하며 조종권을 옮깁니다.";
    button.disabled = true;
    button.setAttribute("aria-pressed", "false");
    button.addEventListener("click", () => onCommand({ type: "cheat-switch-tribe", tribe: tribe.key }, true));
    tribes.append(button);
    return { tribe: tribe.key, button };
  });
  actions.append(...buttons, tribes);
  panel.append(title, actions);
  document.querySelector(".stage").append(panel);
  return {
    update(enabled, disabled, tribe, ended) {
      panel.hidden = !enabled;
      for (const button of buttons) button.disabled = disabled || ended;
      for (const entry of tribeButtons) {
        const current = entry.tribe === tribe;
        entry.button.disabled = disabled || current;
        entry.button.setAttribute("aria-pressed", String(current));
      }
    }
  };
}

return { createCheats };
})();
modules["client/terrain-codex.mjs"] = (() => {
const { RESOURCE_TYPES, RESOURCE_HABITATS } = modules["server/resources.mjs"];
const { RESOURCE_ECONOMY, isEconomyHabitat } = modules["server/economy.mjs"];
const { unitTerrainSpeedMultiplier } = modules["server/attributes.mjs"];
const { tribeTerrainWalkable } = modules["server/tribe-environment.mjs"];

const TERRAIN_CODEX = [
  ["deep", "깊은 물", "deep-water", "지상 유닛은 통행할 수 없습니다."],
  ["shallow", "얕은 물", "shallow-water", "지상 유닛은 통행할 수 없습니다."],
  ["coast", "해안", "coast", "물과 육지가 만나는 가장자리입니다."],
  ["land", "평지", "land", "기본적인 육상 지형입니다."],
  ["grassland", "초원", "grassland", "풀로 덮인 지형입니다."],
  ["forest", "숲", "forest", "나무가 자라는 지형입니다."],
  ["lowMountain", "낮은 산", "low-mountain", "지상 유닛의 이동 속도가 줄어듭니다."],
  ["highMountain", "높은 산", "high-mountain", "지상·비행 유닛의 이동 속도가 줄어듭니다."],
  ["ridge", "능선", "ridge", "몽돌을 제외한 지상 유닛의 이동 속도가 줄어듭니다."],
  ["swamp", "늪", "swamp", "지상 유닛의 이동 속도가 줄어듭니다. 몽돌은 통행할 수 없습니다."],
  ["ford", "여울", "ford", "물을 건널 수 있는 길입니다. 샘방울을 제외한 지상 유닛의 이동 속도가 줄어듭니다."]
].map(([key, name, image, description], type) => {
  const groundSpeed = Math.round(unitTerrainSpeedMultiplier({}, type) * 100);
  const flyingSpeed = Math.round(unitTerrainSpeedMultiplier({ movementType: "flying" }, type) * 100);
  return Object.freeze({
    key, name, type, description, image: "DesignAssets/Terrain/" + image + "-ground.png",
    effect: !tribeTerrainWalkable("bean", type) ? "지상 유닛 통행 불가" : "기본 이동 속도 " + groundSpeed + "%" +
      (groundSpeed !== flyingSpeed ? " · 비행 유닛 " + flyingSpeed + "%" : "")
  });
});

const HAZARD_CODEX = [];

function terrainCodexResources(type, version) {
  const terrain = TERRAIN_CODEX[type];
  if (!terrain) return [];
  return RESOURCE_TYPES.filter(resource => {
    if (resource.harvestLocked) return false;
    if (version >= 11 && RESOURCE_ECONOMY.some(policy => policy.key === resource.key)) return isEconomyHabitat(resource.key, type);
    return RESOURCE_HABITATS.some(habitat => habitat.key === resource.key && habitat.terrains.includes(terrain.key));
  });
}

function terrainCodexCell(world, explored, x, y) {
  const size = world.size;
  if (!Number.isInteger(x) || !Number.isInteger(y) || x < 0 || y < 0 || x >= size || y >= size) return null;
  const index = y * size + x, type = world.terrain[index];
  if (!explored.has(index) || !TERRAIN_CODEX[type]) return null;
  const hazard = HAZARD_CODEX.find(value => value.hazard === world.hazards?.[index]) || null;
  return { x, y, type, terrain: TERRAIN_CODEX[type], hazard,
    speed: !tribeTerrainWalkable("bean", type) ? 0 : unitTerrainSpeedMultiplier({}, type) * (hazard ? 0.5 : 1) };
}

return { TERRAIN_CODEX, HAZARD_CODEX, terrainCodexResources, terrainCodexCell };
})();
